import {PostNativeWalker} from './native-state.mjs';
export const SITE=Object.freeze({mapId:'world:post:nojasan-summit',revision:'NOJASAN_NATIVE_FLOOR_YEJI_PROPOSAL_R2',imageSHA:'c6d76ae2334c032b7630c2fe547e3921731b558b9b324daa3ff912bf7ba7af66',entryId:'post-entry:nojasan-summit',returnId:'post-entry:nojasan-summit:return',pointId:'post:yeji-final',eventId:'YEJI_FINAL',npcId:'NPC_POST_YEJI'});
function rows(bytes,w,h){return Array.from({length:h},(_,y)=>{const row=[];let start=null;for(let x=0;x<=w;x++){if(x<w&&bytes[y*w+x]){if(start===null)start=x}else if(start!==null){row.push([start,x]);start=null}}return row})}
const overlap=(x,y)=>Math.abs(x-960)<=48&&Math.abs(y-360)<=36;
