   if(this.canChallenge()){const phase=this.actorState();if(!phase.ready)return this.lastResult={status:phase.completed?'SOURCE_FINAL_ALREADY_COMPLETED':'SOURCE_FINAL_GATE_LOCKED',executed:false};if(typeof this.challenge!=='function')return this.lastResult={status:'NATIVE_BATTLE_AUTHORITY_NOT_CONNECTED',executed:false};const result=await this.challenge({pointId:SITE.pointId,readNative:()=>this.readNative()});if(this.disposed||stamp!==this.epoch)throw Error('STALE_SCENE_RESPONSE');return this.lastResult=result;}
   if(this.canReturn()){const p=this.world.definition.points[SITE.returnId];if(p?.kind!=='warp'||p.mapId!==SITE.mapId||p.targetMapId!=='world:hub:POST'||p.gate!==null||p.target?.[0]!==33||p.target?.[1]!==7)throw Error('CANONICAL_RETURN_SOURCE_DRIFT');if(this.returnToCanonical)await this.returnToCanonical({pointId:SITE.returnId,readNative:()=>this.readNative()});else await this.world.interact(SITE.returnId);if(this.disposed||stamp!==this.epoch)throw Error('STALE_SCENE_RESPONSE');const confirmed=this.world.snapshot(),grid=this.world.definition.grid;if(grid!==48||confirmed.position.scene!=='world:hub:POST'||confirmed.world?.mapId!=='world:hub:POST'||confirmed.position.x!==33*grid+grid/2||confirmed.position.y!==7*grid+grid/2)throw Error('CANONICAL_RETURN_NOT_CONFIRMED');this.walker.stop();this.epoch++;return this.lastResult={returned:true,via:SITE.returnId,canonicalPosition:this.world.snapshot().position,nativeHubLanding:null};}
