export function drawScene(ctx,{scene,images,camera=[0,0]}){if(scene.world&&images.playerAppearance!==scene.world.snapshot().player.appearance)throw Error('NATIVE_AVATAR_ASSET_IDENTITY_UNAVAILABLE');const [cx,cy]=camera,w=scene.walker;ctx.save();ctx.translate(-cx,-cy);ctx.drawImage(images.map,0,0);const a=[];if(scene.actorState().visible)a.push({y:360,foot:[960,360],image:images.yeji,row:0,col:0});a.push({y:w.y,foot:[w.x,w.y],image:images.player,row:{down:0,right:1,left:2,up:3}[w.facing],col:w.moving?[1,0,2,0][Math.floor(w.walk/26)%4]:0});for(const r of a.sort((x,y)=>x.y-y.y)){const scale=5/12;ctx.imageSmoothingEnabled=true;ctx.drawImage(r.image,r.col*256,r.row*256,256,256,r.foot[0]-128*scale,r.foot[1]-216*scale,256*scale,256*scale)}ctx.restore();return {yejiCount:a.length-1,depthOrder:a.map(r=>r.y)}}
